using Inventory.Domain.Common;

namespace Inventory.Domain.Dispatches;

/// <summary>
/// One confirmed pick (scan) against a reservation. <see cref="ScanId"/> is generated by the device and unique,
/// so a repeated submission of the same scan is recognised and not counted twice. Undos are recorded as negative picks.
/// </summary>
public sealed class PickConfirmation : Entity
{
    public const int ScanIdMaxLength = 64;

    private PickConfirmation() { }

    public Guid DispatchId { get; private set; }
    public Guid LineId { get; private set; }
    public Guid ReservationId { get; private set; }
    public string ScanId { get; private set; } = null!;
    public Guid LocationId { get; private set; }
    public Guid? LotId { get; private set; }
    /// <summary>Signed quantity in base units (negative = undo of <see cref="UndoOfId"/>).</summary>
    public decimal Quantity { get; private set; }
    public string? Barcode { get; private set; }
    public Guid? UndoOfId { get; private set; }
    public DateTimeOffset At { get; private set; }
    public Guid? UserId { get; private set; }

    public static PickConfirmation Create(Guid dispatchId, Guid lineId, Guid reservationId, string scanId, Guid locationId, Guid? lotId,
        decimal quantity, string? barcode, Guid? undoOfId, Guid? userId, DateTimeOffset at)
    {
        var id = (scanId ?? string.Empty).Trim();
        if (id.Length == 0 || id.Length > ScanIdMaxLength)
        {
            throw new DomainRuleException("pick.scan_id_invalid", $"Each scan needs a scan id of 1–{ScanIdMaxLength} characters.");
        }
        return new PickConfirmation
        {
            DispatchId = dispatchId, LineId = lineId, ReservationId = reservationId, ScanId = id, LocationId = locationId, LotId = lotId,
            Quantity = quantity, Barcode = barcode, UndoOfId = undoOfId, UserId = userId, At = at,
        };
    }
}

public enum DiscrepancyType
{
    /// <summary>Not found in the allocated bin.</summary>
    Missing,
    Damaged,
    /// <summary>A product that is not on the dispatch (or not expected in that bin).</summary>
    Unexpected,
    WrongLot,
    Other,
}

/// <summary>A problem reported during picking. Informational: it does not change stock (use an adjustment for that).</summary>
public sealed class DispatchDiscrepancy : Entity
{
    private DispatchDiscrepancy() { }

    public Guid DispatchId { get; private set; }
    public Guid? LineId { get; private set; }
    public Guid? ProductId { get; private set; }
    public Guid? LocationId { get; private set; }
    public DiscrepancyType Type { get; private set; }
    public decimal? Quantity { get; private set; }
    public string? Barcode { get; private set; }
    public string? Note { get; private set; }
    public DateTimeOffset At { get; private set; }
    public Guid? UserId { get; private set; }

    public static DispatchDiscrepancy Create(Guid dispatchId, Guid? lineId, Guid? productId, Guid? locationId, DiscrepancyType type,
        decimal? quantity, string? barcode, string? note, Guid? userId, DateTimeOffset at)
    {
        if (!Enum.IsDefined(type)) throw new DomainRuleException("discrepancy.type_invalid", "Choose a discrepancy type.");
        if (quantity is <= 0) throw new DomainRuleException("discrepancy.quantity", "Quantity must be greater than zero.");
        if (type == DiscrepancyType.Other && string.IsNullOrWhiteSpace(note))
        {
            throw new DomainRuleException("discrepancy.note_required", "Describe the problem.");
        }
        return new DispatchDiscrepancy
        {
            DispatchId = dispatchId, LineId = lineId, ProductId = productId, LocationId = locationId, Type = type, Quantity = quantity,
            Barcode = Text.Optional(barcode, 64, "discrepancy.barcode_invalid", "Barcode"),
            Note = Text.Optional(note, 500, "discrepancy.note_invalid", "Note"),
            UserId = userId, At = at,
        };
    }
}

/// <summary>Proof of delivery: receiver name, a signature drawn on the device and at least one photo (stored files).</summary>
public sealed class ProofOfDelivery : Entity
{
    private ProofOfDelivery() { }

    public Guid DispatchId { get; private set; }
    public string ReceiverName { get; private set; } = null!;
    public DateTimeOffset DeliveredAt { get; private set; }
    public Guid SignatureFileId { get; private set; }
    public string? Notes { get; private set; }
    public DateTimeOffset RecordedAt { get; private set; }
    public Guid? RecordedBy { get; private set; }

    public static ProofOfDelivery Create(Guid dispatchId, string receiverName, DateTimeOffset deliveredAt, Guid signatureFileId, string? notes, Guid? userId, DateTimeOffset at)
    {
        if (deliveredAt > at.AddMinutes(5)) throw new DomainRuleException("pod.future", "The delivery time cannot be in the future.");
        return new ProofOfDelivery
        {
            DispatchId = dispatchId,
            ReceiverName = Text.Required(receiverName, 120, "pod.receiver_required", "Receiver name"),
            DeliveredAt = deliveredAt,
            SignatureFileId = signatureFileId,
            Notes = Text.Optional(notes, 1000, "pod.notes_invalid", "Notes"),
            RecordedAt = at,
            RecordedBy = userId,
        };
    }
}
